#include <c-ray/c-ray.h>
#include <stdio.h>
#include <math.h>
#include <nodes/bsdfnode.h>
#include <nodes/colornode.h>
#include <datatypes/hitrecord.h>
#include <renderer/samplers/sampler.h>
int main(void){struct cr_renderer*r=cr_new_renderer();struct cr_scene*s=cr_renderer_scene_get(r);cr_renderer_set_num_pref(r,cr_renderer_threads,1);cr_renderer_set_num_pref(r,cr_renderer_samples,2);cr_renderer_set_num_pref(r,cr_renderer_bounces,2);cr_camera c=cr_camera_new(s);cr_camera_set_num_pref(s,c,cr_camera_res_x,12);cr_camera_set_num_pref(s,c,cr_camera_res_y,12);cr_camera_set_num_pref(s,c,cr_camera_pose_z,-4);cr_camera_update(s,c);struct cr_color_node color={.type=cr_cn_constant,.arg.constant={0.5,0.25,0.1,1}};struct cr_shader_node mat={.type=cr_bsdf_diffuse,.arg.diffuse.color=&color};cr_material_set set=cr_scene_new_material_set(s);cr_material_set_add(s,set,&mat);cr_sphere sphere=cr_scene_add_sphere(s,1);cr_instance i=cr_instance_new(s,sphere,cr_object_sphere);cr_instance_bind_material_set(s,i,set);struct cr_color_node white={.type=cr_cn_constant,.arg.constant={1,1,1,1}};struct cr_shader_node bg={.type=cr_bsdf_background,.arg.background.color=&white};cr_scene_set_background(s,&bg);struct sampler*sam=sampler_new();sampler_init(sam,Halton,0,2,1);struct lightRay ray={.direction={0,0,-1}};struct hitRecord rec={.incident=&ray,.surfaceNormal={0,0,1},.hitPoint={0,0,0},.uv={0.2,0.3}};const struct bsdfNode*node=build_bsdf_node(s,&mat);struct bsdfSample bs=node->sample(node,sam,&rec);if(fabsf(bs.weight.red-0.5f)>1e-6)return 4;printf("DIFFUSE_SAMPLE red=%.3f\n",bs.weight.red);sampler_destroy(sam);cr_renderer_render(r);struct cr_bitmap*b=cr_renderer_get_result(r);if(!b||b->precision!=cr_bm_float||b->width!=12||b->height!=12)return 1;double sum=0;for(size_t k=0;k<b->width*b->height*4;k++){float v=b->data.float_ptr[k];if(!isfinite(v))return 2;sum+=v;}printf("API_RENDER pixels=%zu sum=%.8f\n",b->width*b->height,sum);cr_destroy_renderer(r);return sum>0?0:3;}
